# int_to_roman :: (1,)
def int_to_roman(n):
    pairs = [(1000,'M'),(900,'CM'),(500,'D'),(400,'CD'),(100,'C'),(90,'XC'),(50,'L'),(40,'XL'),(10,'X'),(9,'IX'),(5,'V'),(4,'IV'),(1,'I')]
    out = ''
    for v, sym in pairs:
        while n >= v:
            out += sym
            n -= v
    return out

if __name__ == '__main__':
    print(int_to_roman((1,)))

